import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_an_unconverted_session():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_last_duplicate_id_wins_before_sorting():
    old = {"id": "x", "day": 8, "converted": True}
    new = {"id": "x", "day": 2, "converted": False}
    other = {"id": "a", "day": 2, "converted": True}
    first = {"id": "z", "day": 1, "converted": None}
    assert dedupe_sessions([old, new, other, first]) == [first, other, new]


def test_parse_skips_comments_and_blank_lines_and_strips_fields():
    assert parse_session_log(["", " \t", "  # ignored", " a , 2 , 0 ", "b,3, "]) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["missing,fields", "too,3,1,many", "a,no,1"])
def test_parse_error_includes_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log(["# comment", " ", bad_line])


def test_daily_counts_include_zero_days_and_exclude_outside_range():
    events = [{"day": d, "converted": True} for d in (0, 2, 2, 4)]
    assert daily_conversion_counts(events, 1, 3) == [0, 2, 0]
    assert daily_conversion_counts(events, 3, 1) == []


@pytest.mark.parametrize("days,expected", [(0, 0), (1, 3), (4, 6)])
def test_trailing_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_summary_uses_weighted_rate_and_calendar_days():
    groups = {
        "a": [{"day": 1, "converted": True}],
        "b": [{"day": 1, "converted": True}, {"day": 4, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert pooled_conversion_rate({}) == 0.0


def test_group_order_and_empty_groups():
    groups = {"z": [{"converted": True}], "b": [{"converted": False}], "e": [], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 8) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("e", None), ("z", 1.0)]


@pytest.mark.parametrize("counts,expected", [([], 0), ([-1, 0], 0), ([1, 0, 2, 1, -1, 1], 2)])
def test_longest_streak_counts_only_consecutive_positive_days(counts, expected):
    assert longest_conversion_streak(counts) == expected
